import 'package:flutter/services.dart';

/// Asset path for public Google IPv4 prefixes (force-proxy under DedProxy-style
/// IP-first routing). Generated by `mobile/scripts/fetch-goog-cidrs.ps1`.
const kYoutubeGoogleCidrAsset = 'assets/rules/youtube-google.cidr';

/// Load and parse [kYoutubeGoogleCidrAsset] (one CIDR per line; `#` comments).
Future<List<String>> loadYoutubeGoogleCidrs({
  AssetBundle? bundle,
}) async {
  final raw = await (bundle ?? rootBundle).loadString(kYoutubeGoogleCidrAsset);
  return parseYoutubeGoogleCidrs(raw);
}

/// Pure parser for unit tests (no Flutter binding).
List<String> parseYoutubeGoogleCidrs(String raw) {
  final out = <String>[];
  for (final line in raw.split('\n')) {
    final trimmed = line.trim();
    if (trimmed.isEmpty || trimmed.startsWith('#')) {
      continue;
    }
    out.add(trimmed);
  }
  return out;
}
